assert.match(cohort.id ?? '', /^[A-Za-z0-9._-]{1,128}$/, 'COHORT_ID must name the frozen replay')
assert.match(cohort.manifestSha256 ?? '', /^[a-f0-9]{64}$/, 'COHORT_MANIFEST_SHA256 must bind the complete manifest')
assert(Number.isFinite(Date.parse(cohort.requestedAt ?? '')), 'COHORT_REQUESTED_AT must record the shared request instant')
assert.equal(new Date(cohort.requestedAt).toISOString(), cohort.requestedAt, 'Request instant must use canonical UTC ISO form')
assert(source && isAbsolute(source), 'SOURCE_ROOT must name an absolute source checkout')
assert(output && isAbsolute(output), 'PROVENANCE_OUTPUT must name an absolute evidence directory')
assert.match(expected ?? '', /^[a-f0-9]{40}$/, 'SOURCE_HEAD must be immutable')
assert(['before', 'after'].includes(phase), 'PROVENANCE_PHASE must be before or after')
assert(['native', 'windows', 'alpine'].includes(caseName), 'PROVENANCE_CASE must name a frozen route')
