const indexEntries = execFileSync('git', ['ls-files', '-v', '-z'], { cwd: source, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 }).split('\0').filter(Boolean)
assert(indexEntries.every(entry => entry[0] !== 'S' && !/[a-z]/.test(entry[0])), 'Immutable source index must not hide tracked inputs with assume-unchanged or skip-worktree flags')
const tracked = execFileSync('git', ['ls-files', '-z'], { cwd: source, encoding: 'utf8' }).split('\0').filter(Boolean)
const packageRoots = ['package/music-player/desktop-app', 'package/music-player/truepeak-core', ...(caseName === 'alpine' ? ['package/cli/nested-wayland-session'] : [])]
const metadataNames = new Set(['mise.toml', 'mise.no-env.toml', 'mise.lock', 'package.json', 'Cargo.toml', 'Cargo.lock', 'config.toml', 'coverage-baseline.json', 'Containerfile.alpine'])
const paths = tracked.filter(path => {
  const name = path.slice(path.lastIndexOf('/') + 1)
  const rootConfiguration = !path.includes('/') && (metadataNames.has(name) || ['.toml', '.json', '.jsonc', '.yaml', '.yml'].some(extension => name.endsWith(extension)) || name.includes('.config.'))
  const packageConfiguration = packageRoots.some(prefix => path.startsWith(prefix + '/')) && (metadataNames.has(name) || name.startsWith('tsconfig.') || name.includes('.config.') || path.includes('/.cargo/'))
  return rootConfiguration || path.startsWith('.cargo/') || ['Cargo.toml', 'Cargo.lock'].includes(name) || packageConfiguration
}).toSorted()
for (const required of ['mise.toml', 'mise.lock', 'package/music-player/desktop-app/Cargo.toml', 'package/music-player/desktop-app/Cargo.lock', 'package/music-player/desktop-app/mise.toml']) assert(paths.includes(required), 'Required source input is absent: ' + required)
const inputs = Object.fromEntries(paths.map(path => { const bytes = readFileSync(join(source, path)); assert.deepEqual(bytes, execFileSync('git', ['show', 'HEAD:' + path], { cwd: source, maxBuffer: 16 * 1024 * 1024 }), 'Configured source input differs: ' + path); return [path, { bytes: bytes.length, sha256: sha256(bytes) }] }))
const identity = { head: git(['rev-parse', 'HEAD']), trackedStatus: git(['status', '--porcelain', '--untracked-files=no']), sourceTree: git(['rev-parse', 'HEAD^{tree}']), inputs }
const harnessRevision = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim()
if (process.env.CI === 'true' || process.env.GITHUB_ACTIONS === 'true') assert.match(process.env.GITHUB_SHA ?? '', /^[a-f0-9]{40}$/, 'Provider harness revision is required in CI')
if (process.env.GITHUB_SHA) assert.equal(harnessRevision, process.env.GITHUB_SHA, 'Provenance harness differs from dispatched workflow revision')
async function readContentsApi({ path }) {
  const token = process.env.GH_TOKEN ?? process.env.GITHUB_TOKEN
  if (process.env.CI === 'true' || process.env.GITHUB_ACTIONS === 'true') assert(token, 'Contents API authentication is required in CI')
  const url = 'https://api.github.com/repos/Aquaticats/Monochromatic/contents/' + path + '?ref=main'
  const response = await fetch(url, { headers: { Accept: 'application/vnd.github.object+json', 'User-Agent': 'Monochromatic-Depot-Trial', ...(token ? { Authorization: 'Bearer ' + token } : {}) }, signal: AbortSignal.timeout(30000) })
  assert.equal(response.status, 200, 'Common manifest Contents API request failed')
  const text = await response.text()
  assert(Buffer.byteLength(text) < 2 * 1024 * 1024, 'Contents API envelope exceeds the manifest transport bound')
  const envelope = JSON.parse(text)
  assert.equal(envelope.encoding, 'base64', 'Contents API must return base64 file bytes')
  assert.equal(envelope.type, 'file')
  assert.equal(envelope.path, path)
  assert.equal(typeof envelope.content, 'string')
  const encoded = envelope.content.replace(/\s+/g, '')
  assert.match(encoded, /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/)
  const bytes = Buffer.from(encoded, 'base64')
  assert(bytes.length < 1024 * 1024, 'Common manifest must be below one MiB')
  assert.equal(bytes.length, envelope.size)
  assert.equal(bytes.toString('base64'), encoded, 'Contents API base64 must preserve exact bytes')
  return { bytes, path, repository: 'Aquaticats/Monochromatic', ref: 'main', url, gitBlob: envelope.sha, sha256: sha256(bytes) }
}
const caseId = caseName === 'native' && expected === 'cb95cf6d785c3073c192b95f0632cdae7b910894' ? 'native' : 'desktop'
const routeId = caseName === 'native' ? caseId === 'native' ? 'native.hosts' : 'desktop.macos' : 'desktop.' + caseName
const localCasePath = '.depot/manifests/' + caseId + '.json'
const localCaseBytes = readFileSync(join(process.cwd(), localCasePath))
assert.deepEqual(localCaseBytes, execFileSync('git', ['show', 'HEAD:' + localCasePath], { maxBuffer: 1024 * 1024 }), 'Local case manifest must equal its committed harness blob')
const localCase = JSON.parse(localCaseBytes)
assert.equal(localCase.completeGraph, true, 'Final route requires a frozen complete case manifest')
assert.equal(localCase.caseId, caseId)
assert.equal(localCase.sourceRevision, expected, 'Local case source differs from the immutable consumer source')
const contents = await readContentsApi({ path: 'doc/audit/depot-complete-cohort-' + cohort.id + '.json' })
assert.equal(contents.sha256, cohort.manifestSha256, 'Common manifest bytes differ from the dispatch digest')
const common = JSON.parse(contents.bytes)
assert.equal(common.schemaVersion, 1)
assert.equal(common.cohortId, cohort.id)
const selectedCase = common.cases?.[caseId]
assert.equal(selectedCase?.sourceRevision, expected)
assert.equal(selectedCase.baseRevision, localCase.baseRevision)
assert.equal(selectedCase.manifestSha256, sha256(localCaseBytes), 'Common case digest differs from the local frozen case')
const selectedRoute = common.routes?.[routeId]
assert.equal(selectedRoute?.caseId, caseId)
assert.equal(selectedRoute.harnessRevision, harnessRevision, 'Common route differs from actual harness HEAD')
assert.equal(selectedRoute.workflow, '.github/workflows/music-player-windows.yml')
const commonManifest = { path: contents.path, repository: contents.repository, ref: contents.ref, gitBlob: contents.gitBlob, bytes: contents.bytes.length, sha256: contents.sha256, caseId, routeId, case: selectedCase, route: selectedRoute, localCaseSha256: sha256(localCaseBytes), document: common }
const record = { schemaVersion: 1, event: 'source-provenance', commonManifest, caseName, phase, cohort, observedAt: new Date().toISOString(), expectedSource: expected, harnessRevision, verifierNode: process.version, platform: process.platform, architecture: process.arch, identity }
mkdirSync(output, { recursive: true, mode: 0o700 })
writeFileSync(join(output, phase + '.json'), JSON.stringify(record, null, 2) + '\n')
console.log(JSON.stringify(record))
assert.equal(identity.head, expected, 'Consumer checkout differs from immutable source revision')
assert.equal(identity.trackedStatus, '', 'Consumer changed tracked historical source')
if (phase === 'after') {
  const before = JSON.parse(readFileSync(join(output, 'before.json'), 'utf8'))
  assert.equal(before.expectedSource, expected)
  assert.deepEqual(before.cohort, cohort, 'Replay context changed between consumer boundaries')
  assert.equal(before.harnessRevision, harnessRevision)
  assert.deepEqual(before.commonManifest, commonManifest, 'Canonical common manifest changed between consumer boundaries')
  assert.deepEqual(identity, before.identity, 'Consumer changed frozen source or input hashes')
}

