import { strict as assert } from 'node:assert';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { homedir } from 'node:os';
import { join } from 'node:path';

//region Compare committed workflow configuration and unchanged authored inputs.
const root = join(homedir(), 'Monochromatic');
const cwd = join(homedir(), 'temp/agent/depot-coherent-native-worktree');
const { parse } = createRequire(import.meta.url)(join(root, 'node_modules/.pnpm/yaml@2.9.1/node_modules/yaml'));
const originalRevision = '2032975cbad924e63ac98bc69e14a56b20288275';
const workflowPath = '.github/workflows/music-player-windows.yml';
const git = args => execFileSync('git', args, { cwd, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 });
const currentRevision = git(['rev-parse', 'HEAD']).trim();
const ref = git(['branch', '--show-current']).trim();
assert.equal(git(['status', '--porcelain=v1', '-z']), '');
assert.equal(git(['ls-remote', 'origin', `refs/heads/${ref}`]).trim().split(/\s/u)[0], currentRevision);
const original = parse(git(['show', `${originalRevision}:${workflowPath}`]));
const currentBytes = readFileSync(join(cwd, workflowPath));
assert.equal(currentBytes.toString(), git(['show', `HEAD:${workflowPath}`]));
const current = parse(currentBytes.toString());
const names = [
  'Build release artifact through the package task',
  'Run all-target Clippy through the package task',
  'Run every nextest case with the source task body',
  'Exercise the built release command',
];
const expected = structuredClone(original);
for (const name of names) {
  const step = expected.jobs.native.steps.find(step => step.name === name);
  assert(step);
  step.if = step.if.replace(' }}', " && steps.provenance-before.outcome == 'success' }}");
}
assert.deepEqual(current, expected, 'Only the four requested consumer conditions may change');
const unchanged = ['package/dev-script/task-util/mise.toml', '.depot/manifests/native.json', '.depot/manifests/desktop.json'].map(path => {
  const before = git(['show', `${originalRevision}:${path}`]);
  const after = git(['show', `HEAD:${path}`]);
  assert.equal(after, before, path);
  assert.equal(readFileSync(join(cwd, path), 'utf8'), after);
  return { path, sha256: createHash('sha256').update(after).digest('hex'), byteIdentical: true };
});
//endregion

//region Exercise only the exact configured boolean grammar, then remove the new predicates in memory.
function conditionEligible({ condition, state }) {
  const pattern = /^\$\{\{\s*!cancelled\(\) && steps\.(identity|build)\.outcome == 'success'( && steps\.provenance-before\.outcome == 'success')?\s*\}\}$/u;
  const match = pattern.exec(condition);
  assert(match, condition);
  return !state.cancelled && state[match[1]] === 'success'
    && (match[2] === undefined || state.before === 'success');
}

function decisions({ workflow, state }) {
  return names.map(name => {
    const step = workflow.jobs.native.steps.find(step => step.name === name);
    return { name, condition: step.if, eligible: conditionEligible({ condition: step.if, state }) };
  });
}

const accepted = { cancelled: false, identity: 'success', build: 'success', before: 'success' };
const controls = [
  { name: 'accepted-common-before', state: accepted, expected: [true, true, true, true] },
  { name: 'failed-common-before', state: { ...accepted, before: 'failure' }, expected: [false, false, false, false] },
  { name: 'skipped-common-before', state: { ...accepted, before: 'skipped' }, expected: [false, false, false, false] },
  { name: 'canceled-workflow', state: { ...accepted, cancelled: true }, expected: [false, false, false, false] },
  { name: 'failed-build-preserves-independent-clippy-and-nextest', state: { ...accepted, build: 'failure' }, expected: [true, true, true, false] },
].map(control => {
  const observed = decisions({ workflow: current, state: control.state });
  assert.deepEqual(observed.map(item => item.eligible), control.expected, control.name);
  return { ...control, observed, passed: true };
});
const removed = structuredClone(current);
for (const step of removed.jobs.native.steps.filter(step => names.includes(step.name))) {
  step.if = step.if.replace(" && steps.provenance-before.outcome == 'success'", '');
}
const failedState = { ...accepted, before: 'failure' };
const counterfactual = decisions({ workflow: removed, state: failedState });
assert(counterfactual.every(item => item.eligible), 'Removal must expose every missing common prerequisite');
const originalFailedBefore = decisions({ workflow: original, state: failedState });
assert.deepEqual(counterfactual, originalFailedBefore);
//endregion

const result = {
  observedAt: new Date().toISOString(), originalRevision, currentRevision, ref,
  workflow: workflowPath, workflowSha256: createHash('sha256').update(currentBytes).digest('hex'),
  onlyRequestedConditionFieldsChanged: true, originalConsumerCommandsUnchanged: true,
  independentSourceIdentityRecordingUnchanged: true, unchanged,
  controls, guardRemoval: { state: failedState, decisions: counterfactual, invalidAcceptances: 4 },
  scope: 'Local truth-table controls inspect the exact configured restricted boolean forms. They do not emulate the whole GitHub expression language or establish provider execution; the actual negative pilot is separate.',
};
writeFileSync('native-common-consumer-gate-controls.json', `${JSON.stringify(result, null, 2)}\n`);
console.log(JSON.stringify({ currentRevision, controlsPassed: controls.length, invalidAcceptancesAfterGuardRemoval: 4, sourceAndGuardInputsUnchanged: true }));
